class Task:
    def __init__(self, title, category):
        self.title = title
        self.category = category

    def __eq__(self, other):
        if not isinstance(other, Task):
            return NotImplemented
        return (self.title, self.category) == (other.title, other.category)

def snapshot_key(task):
    return (task.title, task.category)

def __snapshot_preserved():
    task = Task("read", "study")
    key = snapshot_key(task)
    task.title = "write"
    return key == ("read", "study") and snapshot_key(task) == ("write", "study")
